from topics_a import t, T
G='gp'
t('private-gp',G,'a private GP',"A private GP offers longer, faster appointments, often the same or next day, for the same range of everyday medical problems an NHS GP sees, plus referrals, tests and certificates.",["Appointments of 15 to 30 minutes are common.","Video consultations suit many problems.","Share notes with your NHS GP."])
t('private-doctor',G,'a private doctor',"Private doctors include private GPs and specialists who see patients on a self-pay or insured basis, typically with shorter waits.",["Check GMC registration.","Ask what is included in the fee.","Keep your NHS GP informed."])
t('private-practice-doctor',G,'a doctor in private practice',"Doctors in private practice may be GPs or specialists running their own clinics or working from private hospitals.",["Ask about appointment length.","Check the clinic's regulator.","Clarify follow-up arrangements."])
t('evening-private-gp',G,'an evening private GP',"Evening private GP appointments suit people who cannot easily leave work or caring duties during the day.",["Many clinics open late on weekdays.","Video appointments extend hours further.","Pharmacies may be closed for prescriptions late at night."])
t('private-prescription',G,'a private prescription',"A private prescription is issued by a doctor or other prescriber outside the NHS; you pay the prescriber's fee and the pharmacy's price for the medicine.",["Some medicines are cheaper on private prescription than the NHS charge, others are not.","Controlled drugs have extra rules.","A consultation is needed first."])
t('private-referral',G,'a private referral',"A private referral letter from a GP lets you see a private specialist or have a scan, and is often required by insurers.",["Insurers may need a referral before authorising.","Open referrals give more choice.","Bring the letter to your first appointment."])
t('private-paediatrician',G,'a private paediatrician',"Private paediatricians are children's doctors who assess and treat conditions such as allergies, growth, development, asthma and recurring infections.",["A GP referral is often preferred.","Bring the child's red book.","Ask about follow-up arrangements."],hub='private-healthcare')
t('private-healthcare',G,'private healthcare',"Private healthcare covers GP appointments, specialist consultations, diagnostics and treatment paid for by you or an insurer, alongside NHS care.",["Self-pay and insured routes differ.","Package prices help budgeting.","Emergency care stays with the NHS."],hub='private-healthcare')
t('health-screening',G,'health screening',"Private health screening checks markers such as cholesterol, blood sugar, blood pressure and other tests, depending on the package.",["Choose tests based on your risks.","Results need explaining by a clinician.","More tests are not always better."])
t('blood-test',G,'a private blood test',"Private blood tests let you check things like iron, thyroid, vitamin levels or hormones quickly, with results reviewed by a clinician.",["Fasting may be needed for some tests.","Home kits are available for some tests.","Ask who will explain results."])
t('allergy-clinic',G,'an allergy clinic',"Allergy clinics investigate food, environmental and drug allergies with history-taking, skin prick and blood tests, and create management plans.",["Bring a diary of reactions.","Stop antihistamines before testing if told to.","Anaphylaxis needs an emergency plan."],hub='private-healthcare')
t('private-allergy-clinic',G,'a private allergy clinic',"Private allergy clinics offer faster access to allergists for testing, food challenges and treatment plans for adults and children.",["Specialist allergists are best for complex cases.","Unvalidated tests should be avoided.","Ask about immunotherapy."],hub='private-healthcare')
t('menopause-clinic',G,'a menopause clinic',"Menopause clinics assess symptoms and discuss treatment options, including HRT, for perimenopause and menopause.",["Track symptoms before your appointment.","Ask about British Menopause Society accreditation.","HRT can often be continued via your GP."])
t('private-menopause-clinic',G,'a private menopause clinic',"Private menopause clinics offer longer appointments with doctors who have a special interest in menopause care.",["Ask about the clinician's menopause training.","Bring blood test results if any.","Discuss shared care with your GP."])
P='specialist'
t('consultant-appointment',P,'a private consultant appointment',"A private consultant appointment gives you a specialist's assessment, diagnosis and treatment plan, often within days or weeks.",["Bring a referral letter if you have one.","Ask what tests are likely.","Get costs in writing."])
t('cardiologist',P,'a cardiologist',"Cardiologists assess and treat heart conditions such as palpitations, chest pain, high blood pressure, heart failure and valve problems.",["Tests may include ECG, echo and monitors.","Chest pain now needs 999, not a booking.","Bring a list of medicines."])
t('dermatologist',P,'a dermatologist',"Dermatologists diagnose and treat skin, hair and nail conditions, including eczema, acne, psoriasis, moles and skin cancer.",["Photos of flare-ups help.","Changing moles should be seen promptly.","Check GMC specialist registration."])
t('mole-check',P,'a mole check',"Mole checks use dermoscopy to assess moles for signs of skin cancer, with removal or monitoring where needed.",["Look for changes in shape, colour or size.","Mole mapping tracks changes over time.","Suspicious moles need urgent review."])
t('cyst-removal',P,'cyst removal',"Cyst and lump removal is usually a minor procedure under local anaesthetic, after assessment to confirm the diagnosis.",["New or growing lumps need medical assessment.","Removal may leave a scar.","Ask about histology."])
t('ent',P,'an ENT specialist',"ENT specialists treat ear, nose and throat conditions, including hearing problems, sinus issues, tonsils, voice and balance.",["Bring hearing test results.","Some problems need a camera examination.","Ask about surgical and non-surgical options."])
t('gynaecologist',P,'a gynaecologist',"Gynaecologists treat conditions such as heavy periods, endometriosis, fibroids, pelvic pain and menopause problems.",["Track your cycle and symptoms.","Scans are often arranged quickly.","Ask about treatment options."])
t('endoscopy',P,'an endoscopy',"An endoscopy uses a camera to examine the oesophagus, stomach or bowel, to investigate symptoms such as reflux, pain or bleeding.",["Preparation instructions matter.","Sedation may be offered.","Arrange someone to take you home if sedated."])
t('colonoscopy',P,'a colonoscopy',"A colonoscopy examines the large bowel with a camera to investigate symptoms or screen for polyps and cancer.",["Bowel preparation is essential.","Polyps can be removed during the test.","Report bleeding to a doctor promptly."])
t('ct-scan',P,'a CT scan',"CT scans use X-rays to create detailed cross-sectional images; they must be clinically justified and referred by a qualified practitioner.",["A referral is required.","CT involves radiation; benefits should outweigh risks.","Contrast may be needed."])
t('hernia-repair',P,'hernia repair',"Hernia repair surgery treats inguinal, umbilical and other hernias, often as a day case using open or keyhole techniques.",["A painful, hard hernia needs urgent care.","Ask about keyhole versus open repair.","Plan time off lifting."])
t('hip-replacement',P,'a hip replacement',"Hip replacement surgery replaces a damaged joint to relieve pain and improve movement, usually for arthritis.",["Ask about the surgeon's volume and outcomes.","Rehabilitation is key.","Check what the package includes."])
t('knee-replacement',P,'a knee replacement',"Knee replacement surgery replaces worn joint surfaces to reduce pain and restore movement.",["Partial and total replacements exist.","Physiotherapy afterwards matters.","Recovery takes months."])
t('cataract-surgery',P,'cataract surgery',"Cataract surgery replaces a cloudy lens with an artificial one, usually as a day case under local anaesthetic.",["Lens options vary.","Ask about the surgeon's experience.","Plan for driving restrictions."])
